@js:(function(){
var r=result.replace(/\\"/g,'"').replace(/\\\//g,'/');
var m=r.match(/hlsUrl":"(https:[^"]+)/);
if(m) return m[1];
var mu=r.match(/"url":"(https:[^"]+\.m3u8[^"]*)"/);
if(mu) return mu[1];
var em=r.match(/"episode":\s*\{[^}]*?"id":"([^"]+)"/);
var eid=em?em[1]:'';
var u1=(baseUrl||'').replace(/\/\d+$/,'/1');
var h1='';
try{ h1=java.connect(u1, {"User-Agent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"}).body(); }catch(e){}
if(!h1){ try{ h1=java.ajax(u1); }catch(e){} }
var r1=String(h1).replace(/\\"/g,'"').replace(/\\\//g,'/');
var pm=r1.match(/hlsUrl":"(https:[^"]+)/);
var prefix=pm?pm[1].replace(/[^\/]+\/video\.mp4$/,''):'';
return prefix+eid+'/video.mp4';
})()
